"""Prepare DA-only dynamic reserve research proposals; no optimization is run.
Independent forward-generator errors, not a calibrated conditional forecast law.
"""
from pathlib import Path
import argparse,copy,hashlib,json,sys,time
import numpy as np,pandas as pd
ap=argparse.ArgumentParser();ap.add_argument('--source-run',type=Path,required=True);ap.add_argument('--code-root',type=Path,required=True);ap.add_argument('--out',type=Path,required=True);ap.add_argument('--renewable-multiplier',type=float,required=True);ap.add_argument('--first-seed',type=int,default=900000000);ap.add_argument('--samples',type=int,default=4096);a=ap.parse_args();sys.path.insert(0,str(a.code_root/'src'))
from smm.config import load_config
from smm.forecast import generate_profiles
O=a.out;O.mkdir(parents=True,exist_ok=False);cfg=load_config(root=a.source_run/'scenario_snapshot');assert cfg.base['forecast']['model']=='multiscale_v2';assert cfg.T==96 and cfg.dt==.25
seeds=np.arange(a.first_seed,a.first_seed+a.samples,dtype=np.int64);assert cfg.base['seed'] not in seeds
ren=cfg.units['renewable'];cols=['period','time','load_da']+[u['id']+'_da' for u in ren]+[u['id']+'_sched' for u in cfg.units.get('tie',[])];da=pd.read_csv(a.source_run/'profiles.csv',usecols=cols);da=da[cols];assert not any(any(k in c for k in ['actual','_id','_rt']) for c in da.columns)
da.to_csv(O/'DA_only_inputs.csv',index=False,float_format='%.17g');bids=json.loads((a.source_run/'resolved_bids.json').read_text());load=da.load_da.to_numpy();renewable=sum(np.asarray(bids['units'].get(u['id'],{}).get('avail_pmax') or da[u['id']+'_da'],float) for u in ren);tie=sum(da[u['id']+'_sched'].to_numpy() for u in cfg.units.get('tie',[]));r=cfg.mode['reserve'];ctg=max(float(cfg.base.get('n1_loss_mw') or 0),max([u['pmax'] for u in cfg.units['thermal']]+[u['unit_pmax'] for u in cfg.units['hydro']]+[max(u['unit_gen_max'],u['unit_pump']) for u in cfg.units.get('pumped',[])])) if r['include_ctg'] else 0
base=r['rho_L']*load+r['rho_RE']*renewable+ctg;H=(1+r['rho_L'])*load-(1-r['rho_RE'])*renewable-tie+ctg
spec={'status':'frozen_before_error_sampling_no_optimization','source':str(a.source_run),'evaluation_seed_excluded':cfg.base['seed'],'training_seed_first':int(seeds[0]),'training_seed_last':int(seeds[-1]),'samples':len(seeds),'quantile':.95,'quantile_method':'higher','forecast_model':cfg.base['forecast']['model'],'season':cfg.base['season'],'load_scale':cfg.base['load_scale'],'renewable_multiplier':a.renewable_multiplier,'training_generation':'generate_profiles(cfg, independent_seed), never apply_profile_overrides; multiply each already-clipped renewable actual/DA/ID/RT series by declared renewable multiplier once, then clip to nameplate. Frozen load_scale already includes evaluation load multiplier; do not scale load again.','information_boundary':'Only evaluation DA forecast, fixed tie schedule, resolved DA bids, configuration and declared scenario multiplier used. No evaluation actual/ID/RT value read. Synthetic training actual is independently generated.','distribution_boundary':'Forward-generator unconditional clock-time error samples; not actual given observed DA posterior, not measured history, not empirical probability calibration. Actual-to-forecast clipping and all generator temporal/cross-resource correlations preserved.','formula_H':'(1+rho_L)*load-(1-rho_RE)*renewable-fixed_tie+contingency','formula_error':'(1+rho_L)*(training_load_actual-training_load_da)-(1-rho_RE)*sum(training_RE_actual-training_RE_da)','formula_A':'max(0, Q95(error[:,t]))','formula_B':'max(0,Q95(max_{k=t..anchor_block_end}(H_DA[k]-H_DA[t]+error[:,k])))','anchor_blocks':'[00:00,02:00),...,[22:00,24:00); each eight 15-minute periods. B varies within block; not a single blockwide constant. No next-day wrap.','B_scope':'Forward capacity envelope using known DA ramps; does not guarantee that capacity, operating mode, inventory or network delivery can transfer across times.','implementation_if_approved':'DA case.R_up=baseline_R_up+chosen_buffer; preserve RT original requirement and all physical/economic inputs. No change made now.','hashes':{'DA_only_inputs.csv':hashlib.sha256((O/'DA_only_inputs.csv').read_bytes()).hexdigest(),'resolved_bids.json':hashlib.sha256((a.source_run/'resolved_bids.json').read_bytes()).hexdigest(),**{f'config/{n}':hashlib.sha256((a.source_run/'scenario_snapshot/config'/n).read_bytes()).hexdigest() for n in ['base.yaml','units.yaml','modes.yaml']},**{f'source/{n}':hashlib.sha256((a.code_root/'src/smm'/n).read_bytes()).hexdigest() for n in ['forecast.py','forecast_multiscale.py']}}}
(O/'proposal_spec_before_sampling.json').write_text(json.dumps(spec,indent=2,ensure_ascii=False));errors=np.empty((len(seeds),cfg.T));start=time.perf_counter();transfer={u['id']:{'below_zero_resource_period_samples':0,'above_nameplate_resource_period_samples':0,'above_scenario_availability_resource_period_samples':0,'minimum_implied_mw':float('inf'),'maximum_implied_mw':float('-inf')} for u in ren}
for i,seed in enumerate(seeds):
 train=generate_profiles(cfg,seed=int(seed));dr=np.zeros(cfg.T)
 for u in ren:
  actual=np.clip(train[u['id']+'_actual'].to_numpy()*a.renewable_multiplier,0,u['cap']);forecast=np.clip(train[u['id']+'_da'].to_numpy()*a.renewable_multiplier,0,u['cap']);dr+=actual-forecast
  implied=da[u['id']+'_da'].to_numpy()+actual-forecast;q=transfer[u['id']];q['below_zero_resource_period_samples']+=int((implied < -1e-9).sum());q['above_nameplate_resource_period_samples']+=int((implied>u['cap']+1e-9).sum());q['above_scenario_availability_resource_period_samples']+=int((implied>min(u['cap'],u['cap']*a.renewable_multiplier)+1e-9).sum());q['minimum_implied_mw']=min(q['minimum_implied_mw'],float(implied.min()));q['maximum_implied_mw']=max(q['maximum_implied_mw'],float(implied.max()))
 errors[i]=(1+r['rho_L'])*(train.load_actual.to_numpy()-train.load_da.to_numpy())-(1-r['rho_RE'])*dr
 if (i+1)%512==0:print(f'Generated {i+1}/{len(seeds)} independent error paths',flush=True)
A=np.maximum(0,np.quantile(errors,.95,axis=0,method='higher'));B=np.empty(cfg.T)
for t in range(cfg.T):
 end=min(cfg.T,(t//8+1)*8);B[t]=max(0,np.quantile(np.max(errors[:,t:end]+H[None,t:end]-H[t],axis=1),.95,method='higher'))
assert np.all(B>=A-1e-10)
out=pd.DataFrame({'period_zero_based':np.arange(cfg.T),'time':da.time,'H_DA_mw':H,'baseline_R_up_mw':base,'A_extra_up_mw':A,'B_extra_up_mw':B,'A_DA_up_requirement_mw':base+A,'B_DA_up_requirement_mw':base+B,'anchor_block_end_hour':(np.arange(cfg.T)//8+1)*2});out.to_csv(O/'dynamic_reserve_buffers.csv',index=False,float_format='%.17g');np.save(O/'independent_generator_headroom_errors.npy',errors)
def stats(x):return {'min_mw':float(x.min()),'median_mw':float(np.median(x)),'max_mw':float(x.max()),'mean_mw':float(x.mean()),'sum_mw_periods':float(x.sum()),'integral_mw_h':float(x.sum()*cfg.dt),'array_mw':x.tolist()}
result={'A':stats(A),'B':stats(B),'B_dominates_A_every_period':bool(np.all(B>=A-1e-10)),'B_strictly_above_A_periods':int((B>A+1e-10).sum()),'quantile_monte_carlo_error_not_certified':True,'elapsed_generation_s':time.perf_counter()-start,'optimization_executed':False,'hashes':{name:hashlib.sha256((O/name).read_bytes()).hexdigest() for name in ['dynamic_reserve_buffers.csv','independent_generator_headroom_errors.npy','proposal_spec_before_sampling.json']}}
(O/'residual_transfer_domain_diagnostic.json').write_text(json.dumps({'scope':'Diagnostic only: adding unconditional resource errors to evaluation DA can leave physical availability bounds; no extra clipping, no buffer changes, not a conditional or physically reachable scenario guarantee.','resource_period_samples_per_unit':len(seeds)*cfg.T,'resources':transfer},indent=2));
(O/'dynamic_reserve_statistics.json').write_text(json.dumps(result,indent=2));print(json.dumps({k:({x:y for x,y in v.items() if x!='array_mw'} if k in ['A','B'] else v) for k,v in result.items()},indent=2),flush=True)
